event.script:
var campos = xfa.layout.pageContent(xfa.layout.page(this) - 1, "field", false);
var total = 0;
for (var i = 0; i < campos.length; i++) {
  if (campos.item(i).name == "IMPORTE") { total += Number(campos.item(i).rawValue); }
}
this.rawValue = total;
if (total == 0) { this.presence = "invisible"; }   // páginas sin filas (p. ej. solo el bloque final)
